l=A.a(["\ub300\uc218","\ub85c\uadf8","\ub85c\uadf8\uc758\uc815\uc758","\ubc11"],ai0)
l=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc815\uc758 > \ubc11 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["\ub85c\uadf8\uc5d0\uc11c '\ubc11'\uc774\ub780 \ub85c\uadf8\uc758 \uac12\uc744 \uacb0\uc815\ud558\ub294 \uae30\uc900\uc774 \ub418\ub294 \uc218\ub97c \ub9d0\ud569\ub2c8\ub2e4. \ub85c\uadf8 $\\log_a b$\uc5d0\uc11c \uc544\ub798\ucabd\uc5d0 \uc791\uac8c \uc4f0\uc5ec \uc788\ub294 $a$\ub97c \ubc14\ub85c '\ubc11'\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. \ub85c\uadf8\ub294 '\uc5b4\ub5a4 \uc218 $a$\ub97c \uba87 \ubc88 \uacf1\ud574\uc57c $b$\uac00 \ub418\ub294\uac00?'\ub77c\ub294 \uc9c8\ubb38\uc5d0 \ub300\ud55c \ub2f5\uc744 \uad6c\ud558\ub294 \ub3c4\uad6c\uc778\ub370, \uc774\ub54c \uacf1\ud574\uc9c0\ub294 \ub300\uc0c1\uc778 $a$\uac00 \ubc14\ub85c \ubc11\uc758 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \ubc11\uc740 \ub85c\uadf8\uc758 \uad6c\uc870\ub97c \uc9c0\ud0f1\ud558\ub294 \uac00\uc7a5 \uc911\uc694\ud55c \uae30\ucd08\ub77c\uace0 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub85c\uadf8\uac00 \uc218\ud559\uc801\uc73c\ub85c \uc758\ubbf8\ub97c \uac16\uae30 \uc704\ud574\uc11c\ub294 \ubc11 $a$\uc5d0 \uc5c4\uaca9\ud55c \uc870\uac74\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uccab\uc9f8, \ubc11 $a$\ub294 $0$\ubcf4\ub2e4 \ucee4\uc57c \ud569\ub2c8\ub2e4($a > 0$). \ub458\uc9f8, \ubc11 $a$\ub294 $1$\uc774 \uc544\ub2c8\uc5b4\uc57c \ud569\ub2c8\ub2e4($a \\neq 1$). \ub9cc\uc57d \ubc11\uc774 $1$\uc774\ub77c\uba74 $1$\uc744 \uc544\ubb34\ub9ac \uac70\ub4ed\uc81c\uacf1\ud574\ub3c4 \ud56d\uc0c1 $1$\uc774 \ub418\ubbc0\ub85c, $1$\uc774 \uc544\ub2cc \ub2e4\ub978 \uc218\uc5d0 \ub300\ud55c \ub85c\uadf8 \uac12\uc744 \uc815\uc758\ud560 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub610\ud55c \ubc11\uc774 \uc74c\uc218\uc774\uac70\ub098 $0$\uc774\uba74 \uac70\ub4ed\uc81c\uacf1\uc744 \ud560 \ub54c \uac12\uc774 \uc77c\uc815\ud558\uac8c \uc720\uc9c0\ub418\uc9c0 \uc54a\uac70\ub098 \uc815\uc758\ub418\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \ubc1c\uc0dd\ud558\uc5ec \ub85c\uadf8\uc758 \uc131\uc9c8\uc744 \uc720\uc9c0\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.","\uc774\ub7ec\ud55c \ubc11\uc758 \uc870\uac74\uc740 \ub85c\uadf8\uc758 \uc815\uc758\uc778 $x = \\log_a b \\iff a^x = b$\uc5d0\uc11c \ube44\ub86f\ub429\ub2c8\ub2e4. \uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \ubc11 \uc870\uac74\uacfc \ub3d9\uc77c\ud558\uac8c, \ubc11 $a$\uac00 $0$\ubcf4\ub2e4 \ud06c\uace0 $1$\uc774 \uc544\ub2d0 \ub54c \ub85c\uadf8\ud568\uc218\ub294 \uc77c\ub300\uc77c \ub300\uc751 \uad00\uacc4\ub97c \uac00\uc9c0\uba70 \uc548\uc815\uc801\uc778 \uadf8\ub798\ud504\ub97c \ud615\uc131\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub85c\uadf8\ub97c \ub2e4\ub8f0 \ub54c\ub294 \ud56d\uc0c1 \ubc11\uc774 \uc774 \uc870\uac74\uc744 \ub9cc\uc871\ud558\ub294\uc9c0 \uba3c\uc800 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\ub294 \uac83\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc608\uc81c: \ub2e4\uc74c \ub85c\uadf8\uac00 \uc815\uc758\ub418\uae30 \uc704\ud55c \uc2e4\uc218 $x$\uc758 \ubc94\uc704\ub97c \uad6c\ud558\uc2dc\uc624. $\\log_{x-2} (5-x)$","\ud480\uc774 \ub2e8\uacc4: \ub85c\uadf8\uac00 \uc815\uc758\ub418\ub824\uba74 \ubc11 \uc870\uac74\uacfc \uc9c4\uc218 \uc870\uac74 \ub450 \uac00\uc9c0\ub97c \ubaa8\ub450 \ub9cc\uc871\ud574\uc57c \ud569\ub2c8\ub2e4. \uccab\uc9f8, \ubc11 \uc870\uac74\uc5d0 \uc758\ud574 $x-2 > 0$\uc774\uace0 $x-2 \\neq 1$\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $x > 2$\uc774\uace0 $x \\neq 3$\uc785\ub2c8\ub2e4. \ub458\uc9f8, \uc9c4\uc218 \uc870\uac74\uc5d0 \uc758\ud574 $5-x > 0$\uc774\uc5b4\uc57c \ud558\ubbc0\ub85c $x < 5$\uc785\ub2c8\ub2e4. \uc774 \ubaa8\ub4e0 \uc870\uac74\uc744 \uc885\ud569\ud558\uba74 $2 < x < 3$ \ub610\ub294 $3 < x < 5$\uac00 \ub429\ub2c8\ub2e4.","\uc608\uc81c: $\\log_a 8 = 3$\uc744 \ub9cc\uc871\ud558\ub294 \ubc11 $a$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \ud480\uc774: \ub85c\uadf8\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $\\log_a 8 = 3$\uc740 $a^3 = 8$\uacfc \uac19\uc2b5\ub2c8\ub2e4. $8$\uc740 $2$\ub97c \uc138 \ubc88 \uacf1\ud55c \uc218($2^3 = 8$)\uc774\ubbc0\ub85c $a^3 = 2^3$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $a = 2$\uc785\ub2c8\ub2e4. \uc774\ub54c $a=2$\ub294 $a > 0$\uc774\uace0 $a \\neq 1$\uc774\ub77c\ub294 \ubc11\uc758 \uc870\uac74\uc744 \ub9cc\uc871\ud558\ubbc0\ub85c \uad6c\ud558\ub294 \uac12\uc740 $2$\uac00 \ub429\ub2c8\ub2e4."],ai0),"\ubc11",B.o)],ai2),"\ubc11",B.o)],ai3),s3,s3,s3,"concept_\ubc11",0,"","\ub300\uc218 > \ub85c\uadf8 > \ub85c\uadf8\uc758\uc815\uc758 > \ubc11",l,"\ubc11",s3)
k=A.a(["\ubbf8\uc801\ubd84\u2160","\ubbf8\ubd84\uacfc\ucd5c\ub300\ucd5c\uc18c","\ucd5c\ub313\uac12(\ubbf8\ubd84)"],ai0)
k=A.av(s2,A.a([A.au(A.a(["\ubbf8\uc801\ubd84\u2160 > \ubbf8\ubd84\uacfc\ucd5c\ub300\ucd5c\uc18c > \ucd5c\ub313\uac12(\ubbf8\ubd84) \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["\ud568\uc218 $f(x)$\uac00 \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \uc815\uc758\ub420 \ub54c, \uadf8 \uad6c\uac04\uc5d0 \uc18d\ud558\ub294 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f(x) \\leq M$\uc744 \ub9cc\uc871\ud558\ub294 \uc0c1\uc218 $M$\uc774 \uc874\uc7ac\ud558\uace0, $f(c) = M$\uc778 $x=c$\uac00 \uc874\uc7ac\ud55c\ub2e4\uba74, \uc6b0\ub9ac\ub294 $f(c)$\ub97c \ud568\uc218 $f(x)$\uc758 \ucd5c\ub313\uac12\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ubbf8\ubd84 \uac00\ub2a5\ud55c \ud568\uc218\uc5d0\uc11c \ucd5c\ub313\uac12\uc744 \ucc3e\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ub3c4\ud568\uc218 $f'(x)$\ub97c \uad6c\ud558\uc5ec $f'(x)=0$\uc774 \ub418\ub294 \uc9c0\uc810\uc778 '\uc784\uacc4\uc810'\uc744 \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4. \uc774 \uc9c0\uc810\ub4e4\uc740 \ud568\uc218\uac00 \uc99d\uac00\ud558\ub2e4\uac00 \uac10\uc18c\ud558\uac70\ub098, \uac10\uc18c\ud558\ub2e4\uac00 \uc99d\uac00\ud558\ub294 \ub4f1 \ubcc0\ud654\uac00 \uc77c\uc5b4\ub098\ub294 \ud6c4\ubcf4\uc9c0\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.","\uad6c\uccb4\uc801\uc73c\ub85c \ub2eb\ud78c \uad6c\uac04 $[a, b]$\uc5d0\uc11c \uc5f0\uc18d\uc778 \ud568\uc218 $f(x)$\uc758 \ucd5c\ub313\uac12\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, \uad6c\uac04 \ub0b4\uc5d0\uc11c $f'(x)=0$\uc744 \ub9cc\uc871\ud558\ub294 \ubaa8\ub4e0 $x$\uc758 \uac12\uc744 \uad6c\ud569\ub2c8\ub2e4. \ub458\uc9f8, \uad6c\uac04\uc758 \uc591 \ub05d\uc810\uc778 $f(a)$\uc640 $f(b)$\uc758 \uac12\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc14b\uc9f8, \uc704\uc5d0\uc11c \uad6c\ud55c \ubaa8\ub4e0 \ud6c4\ubcf4\uac12\ub4e4($f(a), f(b)$ \ubc0f \uc784\uacc4\uc810\uc5d0\uc11c\uc758 \ud568\uc22b\uac12\ub4e4)\uc744 \uc11c\ub85c \ube44\uad50\ud558\uc5ec \uadf8\uc911 \uac00\uc7a5 \ud070 \uac12\uc744 \uc120\ud0dd\ud569\ub2c8\ub2e4. \uc774\ub54c \uc0ac\uc6a9\ub418\ub294 \ud575\uc2ec \uacf5\uc2dd\uc740 \ub3c4\ud568\uc218\uc758 \ubd80\ud638 \ubcc0\ud654\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774\uba70, $f'(x)$\uc758 \ubd80\ud638\uac00 \uc591(+)\uc5d0\uc11c \uc74c(-)\uc73c\ub85c \ubc14\ub014 \ub54c \uadf8 \uc9c0\uc810\uc774 \uadf9\ub300\uc774\uc790 \ucd5c\ub313\uac12\uc758 \uac15\ub825\ud55c \ud6c4\ubcf4\uac00 \ub429\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c\ub97c \ud1b5\ud574 \ucd5c\ub313\uac12\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud568\uc218 $f(x) = -x^3 + 3x^2 + 9x$\uc758 \uad6c\uac04 $[-2, 4]$\uc5d0\uc11c\uc758 \ucd5c\ub313\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218\ub97c \uad6c\ud558\uba74 $$f'(x) = -3x^2 + 6x + 9$$\uac00 \ub429\ub2c8\ub2e4. \uc774 \ub3c4\ud568\uc218\uac00 $0$\uc774 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uae30 \uc704\ud574 \ubc29\uc815\uc2dd\uc744 \ud480\uba74 $$-3(x^2 - 2x - 3) = -3(x-3)(x+1) = 0$$\uc774 \ub418\uc5b4, $x = -1$ \ub610\ub294 $x = 3$\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \uc784\uacc4\uc810\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uac04 $[-2, 4]$ \ub0b4\uc5d0 \ud3ec\ud568\ub41c \uc784\uacc4\uc810\uacfc \uc591 \ub05d\uc810\uc5d0\uc11c\uc758 \ud568\uc22b\uac12\uc744 \uac01\uac01 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uba3c\uc800 \uc591 \ub05d\uc810\uc778 $x = -2$\uc640 $x = 4$\ub97c \ub300\uc785\ud558\uba74, $$f(-2) = -(-8) + 3(4) + 9(-2) = 8 + 12 - 18 = 2$$\uc774\uace0, $$f(4) = -(64) + 3(16) + 9(4) = -64 + 48 + 36 = 20$$\uc774 \ub429\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c \uc784\uacc4\uc810 $x = -1$\uacfc $x = 3$\uc744 \ub300\uc785\ud558\uba74, $$f(-1) = -(-1) + 3(1) + 9(-1) = 1 + 3 - 9 = -5$$\uc774\uba70, $$f(3) = -(27) + 3(9) + 9(3) = -27 + 27 + 27 = 27$$\uc774 \ub098\uc635\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uad6c\ud55c \ud568\uc22b\uac12\ub4e4\uc744 \ubaa8\ub450 \ube44\uad50\ud569\ub2c8\ub2e4. \ud6c4\ubcf4\uac12\ub4e4\uc740 $f(-2)=2, f(4)=20, f(-1)=-5, f(3)=27$\uc785\ub2c8\ub2e4. \uc774 \uc911\uc5d0\uc11c \uac00\uc7a5 \ud070 \uac12\uc740 $27$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uad6c\uac04 $[-2, 4]$\uc5d0\uc11c \ud568\uc218 $f(x)$\uc758 \ucd5c\ub313\uac12\uc740 $27$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ubbf8\ubd84\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \uadf8\ub798\ud504\uc758 \uac1c\ud615\uc744 \uadf8\ub9ac\uc9c0 \uc54a\uace0\ub3c4 \ud568\uc22b\uac12\ub4e4\uc744 \ube44\uad50\ud558\uc5ec \ucd5c\ub313\uac12\uc744 \uc815\ud655\ud558\uac8c \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),s9,B.o)],ai2),s9,B.o)],ai3),s3,s3,s3,"concept_\ucd5c\ub313\uac12(\ubbf8\ubd84)",0,"","\ubbf8\uc801\ubd84\u2160 > \ubbf8\ubd84\uacfc\ucd5c\ub300\ucd5c\uc18c > \ucd5c\ub313\uac12(\ubbf8\ubd84)",k,s9,s3)
j=A.a(["\uacf5\ud1b5\uc218\ud5591","\uacbd\uc6b0\uc758\uc218","\ud569\uc758\ubc95\uce59","\uc0ac\uac74\uc758\ud569"],ai0)
j=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \ud569\uc758\ubc95\uce59 > \uc0ac\uac74\uc758\ud569 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["[   \"\ub450 \uc0ac\uac74 $A$\uc640 $B$\uac00 \ub3d9\uc2dc\uc5d0 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc744 \ub54c, \uc0ac\uac74 $A$\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c $m$, \uc0ac\uac74 $B$\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c $n$\uc774\ub77c\uace0 \ud558\uba74, \uc0ac\uac74 $A$ \ub610\ub294 \uc0ac\uac74 $B$\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $m+n$\uc785\ub2c8\ub2e4. \uc774\ub97c '\ud569\uc758 \ubc95\uce59'\uc774\ub77c\uace0 \ud558\uba70, \uc77c\uc0c1\uc0dd\ud65c\uc5d0\uc11c '\uc5b4\ub290 \ud55c\ucabd\uc744 \uc120\ud0dd\ud558\ub294 \uc0c1\ud669'\uc744 \uc218\ud559\uc801\uc73c\ub85c \ud45c\ud604\ud55c \uac83\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c '\ub3d9\uc2dc\uc5d0 \uc77c\uc5b4\ub098\uc9c0 \uc54a\ub294\ub2e4'\ub294 \ub9d0\uc740 \ub450 \uc0ac\uac74\uc774 \uc11c\ub85c \uacb9\uce58\ub294 \uacbd\uc6b0\uac00 \uc804\ud600 \uc5c6\ub2e4\ub294 \ub73b\uc73c\ub85c, \uc774\ub97c \uc218\ud559 \uc6a9\uc5b4\ub85c '\ubc30\ubc18\uc0ac\uac74'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4.\",   \"\ud569\uc758 \ubc95\uce59\uc740 \uc0ac\uac74\uc774 3\uac1c \uc774\uc0c1\uc77c \ub54c\ub3c4 \ub611\uac19\uc774 \uc801\uc6a9\ub429\ub2c8\ub2e4. \uc0ac\uac74 $A, B, C$\uac00 \uc11c\ub85c \uacb9\uce58\uc9c0 \uc54a\uac8c \uc77c\uc5b4\ub0a0 \ub54c, \uc0ac\uac74 $A$ \ub610\ub294 $B$ \ub610\ub294 $C$\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 \uac01 \uc0ac\uac74\uc758 \uacbd\uc6b0\uc758 \uc218\ub97c \ubaa8\ub450 \ub354\ud55c $$m + n + k$$\uac00 \ub429\ub2c8\ub2e4. \uc911\uc694\ud55c \uc810\uc740 \uac01 \uc0ac\uac74\uc774 \uc11c\ub85c \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\uc73c\uba74\uc11c \ub3d9\uc2dc\uc5d0 \ubc1c\uc0dd\ud560 \uc218 \uc5c6\ub294 \uc0c1\ud669\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ub450 \uc0ac\uac74\uc774 \ub3d9\uc2dc\uc5d0 \uc77c\uc5b4\ub0a0 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4\uba74, \ub2e8\uc21c\ud788 \ub354\ud558\uae30\ub9cc \ud574\uc11c\ub294 \uc548 \ub418\uace0 \uacb9\uce58\ub294 \ubd80\ubd84\uc744 \uace0\ub824\ud574\uc57c \ud558\ubbc0\ub85c \uc8fc\uc758\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\",   \"\uc608\ub97c \ub4e4\uc5b4, \uc5b4\ub290 \ubd84\uc2dd\uc9d1\uc5d0\uc11c \uae40\ubc25 3\uc885\ub958\uc640 \ub77c\uba74 2\uc885\ub958\ub97c \ud310\ub9e4\ud558\uace0 \uc788\ub2e4\uace0 \uac00\uc815\ud574 \ubd05\uc2dc\ub2e4. \uc774\ub54c \uae40\ubc25 \ud55c \uc904\uc744 \uace0\ub974\uac70\ub098 \ub77c\uba74 \ud55c \uadf8\ub987\uc744 \uace0\ub974\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uae40\ubc25\uc744 \uace0\ub974\ub294 \uc0ac\uac74\uc744 $A$, \ub77c\uba74\uc744 \uace0\ub974\ub294 \uc0ac\uac74\uc744 $B$\ub77c\uace0 \ud558\uba74, \uae40\ubc25\uc744 \uace0\ub974\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $3$, \ub77c\uba74\uc744 \uace0\ub974\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $2$\uc785\ub2c8\ub2e4. \uae40\ubc25\uacfc \ub77c\uba74\uc744 \ub3d9\uc2dc\uc5d0 \uace0\ub974\ub294 \uac83\uc774 \uc544\ub2c8\ub77c '\ub458 \uc911 \ud558\ub098'\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ud569\uc758 \ubc95\uce59\uc744 \uc801\uc6a9\ud569\ub2c8\ub2e4.\",   \"\ub530\ub77c\uc11c \uad6c\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $$3 + 2 = 5$$\uac00 \ub429\ub2c8\ub2e4. \uc989, \ubd84\uc2dd\uc9d1\uc5d0\uc11c \uba54\ub274 \ud558\ub098\ub97c \uc120\ud0dd\ud558\ub294 \ubc29\ubc95\uc740 \ucd1d 5\uac00\uc9c0\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ud569\uc758 \ubc95\uce59\uc740 '\ub610\ub294(~\uac70\ub098)'\uc774\ub77c\ub294 \ud45c\ud604\uc774 \ud3ec\ud568\ub41c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \ub54c \uac00\uc7a5 \uae30\ubcf8\uc774 \ub418\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \ubb38\uc81c \uc0c1\ud669\uc5d0\uc11c \uc120\ud0dd\uc9c0\uac00 \uc11c\ub85c \ubc30\ud0c0\uc801\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\uba74 \uacbd\uc6b0\uc758 \uc218\ub97c \ud6e8\uc52c \uc815\ud655\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\",   \"\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c, \uc8fc\uc0ac\uc704 \ud55c \uac1c\ub97c \ub358\uc84c\uc744 \ub54c 2\uc758 \ubc30\uc218\uac00 \ub098\uc624\uac70\ub098 5\uc758 \uc57d\uc218\uac00 \ub098\uc624\ub294 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 2\uc758 \ubc30\uc218\uac00 \ub098\uc624\ub294 \uc0ac\uac74\uc744 $A$\ub77c\uace0 \ud558\uba74 $A = \\{2, 4, 6\\}$\uc73c\ub85c \uacbd\uc6b0\uc758 \uc218\ub294 $3$\uc785\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c 5\uc758 \uc57d\uc218\uac00 \ub098\uc624\ub294 \uc0ac\uac74\uc744 $B$\ub77c\uace0 \ud558\uba74 $B = \\{1, 5\\}$\ub85c \uacbd\uc6b0\uc758 \uc218\ub294 $2$\uc785\ub2c8\ub2e4. \ub450 \uc0ac\uac74\uc744 \ud655\uc778\ud574 \ubcf4\uba74 \uacb9\uce58\ub294 \uc22b\uc790\uac00 \uc5c6\uc73c\ubbc0\ub85c \ud569\uc758 \ubc95\uce59\uc744 \ubc14\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\",   \"\ucd5c\uc885\uc801\uc73c\ub85c \uad6c\ud558\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $$3 + 2 = 5$$\uc785\ub2c8\ub2e4. \ub9cc\uc57d 2\uc758 \ubc30\uc218\uac00 \ub098\uc624\uac70\ub098 4\uc758 \uc57d\uc218\uac00 \ub098\uc624\ub294 \uacbd\uc6b0\ub77c\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c\uc694? 2\uc758 \ubc30\uc218\ub294 $\\{2, 4, 6\\}$\uc774\uace0 4\uc758 \uc57d\uc218\ub294 $\\{1, 2, 4\\}$\uc785\ub2c8\ub2e4. \uc774\ub54c\ub294 '2'\uc640 '4'\uac00 \ub450 \uc0ac\uac74\uc5d0 \ubaa8\ub450 \ud3ec\ud568\ub418\uc5b4 \uc788\uc73c\ubbc0\ub85c, \ub2e8\uc21c\ud788 \ub354\ud558\uba74 \uacb9\uce58\ub294 \ubd80\ubd84\uc744 \ub450 \ubc88 \uc138\uac8c \ub429\ub2c8\ub2e4. \uc774\ub7f4 \ub54c\ub294 \uacb9\uce58\ub294 \ubd80\ubd84\uc744 \uc81c\uc678\ud558\uace0 \uacc4\uc0b0\ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc744 \ud56d\uc0c1 \uae30\uc5b5\ud558\uc138\uc694.\" ]"],ai0),t0,B.o)],ai2),t0,B.o)],ai3),s3,s3,s3,"concept_\uc0ac\uac74\uc758\ud569",0,"","\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \ud569\uc758\ubc95\uce59 > \uc0ac\uac74\uc758\ud569",j,t0,s3)
i=A.a(["\ub300\uc218","\uc218\uc5f4","\uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569","\ubd80\ubd84\ubd84\uc218"],ai0)
i=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc218\uc5f4 > \uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569 > \ubd80\ubd84\ubd84\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["\ubd80\ubd84\ubd84\uc218\ub780 \ubd84\ubaa8\uac00 \uacf1\uc758 \ud615\ud0dc\ub85c \uc774\ub8e8\uc5b4\uc9c4 \ubd84\uc218\ub97c \uc5ec\ub7ec \uac1c\uc758 \ubd84\uc218\uc758 \ucc28(\ube84\uc148)\ub85c \ub098\ub204\uc5b4 \ud45c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \ub9d0\ud569\ub2c8\ub2e4. \ubcf5\uc7a1\ud55c \ubd84\uc218\uc2dd\uc744 \uac04\ub2e8\ud558\uac8c \ubd84\ud574\ud568\uc73c\ub85c\uc368, \ud2b9\ud788 \uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud560 \ub54c \ud56d\ub4e4\uc774 \uc11c\ub85c \uc0c1\uc1c4\ub418\ub3c4\ub85d \uc720\ub3c4\ud558\uc5ec \uacc4\uc0b0\uc744 \ud68d\uae30\uc801\uc73c\ub85c \uc904\uc5ec\uc8fc\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4. \ubd84\ubaa8\uac00 \ub450 \uc778\uc218\uc758 \uacf1\uc73c\ub85c \ub098\ud0c0\ub09c \ubd84\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc740 \uae30\ubcf8 \uacf5\uc2dd\uc73c\ub85c \ubcc0\ud615\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub450 \uc778\uc218 $A$\uc640 $B$\uc758 \uacf1\uc744 \ubd84\ubaa8\ub85c \uac00\uc9c0\ub294 \ubd84\uc218\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \ubd84\ud574\ub429\ub2c8\ub2e4. $$ \\frac{1}{A \\times B} = \\frac{1}{B - A} \\left( \\frac{1}{A} - \\frac{1}{B} \\right) $$ \uc5ec\uae30\uc11c $A$\uc640 $B$\ub294 \ub2e4\ud56d\uc2dd\uc77c \uc218\ub3c4 \uc788\uace0 \uc218\uc77c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\uc758 \ud575\uc2ec\uc740 \ubd84\ubaa8\uc758 \ucc28\uc774\uc778 $(B-A)$\ub97c \ubd84\ubaa8\uc5d0 \ub098\ub204\uc5b4 \uc90c\uc73c\ub85c\uc368, \uc804\uccb4 \uc2dd\uc758 \uac12\uc740 \uc720\uc9c0\ud558\uba74\uc11c \ubd84\uc218 \ud615\ud0dc\ub97c \ube84\uc148 \uad6c\uc870\ub85c \ubc14\uafb8\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ubd84\uc790\uac00 1\uc774 \uc544\ub2c8\ub77c\uba74, \uadf8 \uc0c1\uc218\ub9cc\ud07c \uc804\uccb4 \uc2dd\uc5d0 \uacf1\ud574\uc8fc\uba74 \ub429\ub2c8\ub2e4.","\ubd80\ubd84\ubd84\uc218\ub97c \ud65c\uc6a9\ud558\uba74 \uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud560 \ub54c '\ub9dd\uc6d0\uae09\uc218(Telescoping Series)'\uc758 \uc6d0\ub9ac\ub97c \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc218\uc5f4\uc758 \uac01 \ud56d\uc744 \ubd80\ubd84\ubd84\uc218\ub85c \ubd84\ud574\ud558\uba74, \uc55e \ud56d\uc758 \ub4b7\ubd80\ubd84\uacfc \ub4a4 \ud56d\uc758 \uc55e\ubd80\ubd84\uc774 \uc11c\ub85c \ub354\ud574\uc9c0\uac70\ub098 \ube7c\uc9c0\uba74\uc11c \uc911\uac04 \ud56d\ub4e4\uc774 \ubaa8\ub450 \uc0ac\ub77c\uc9c0\uace0 \ucc98\uc74c\uacfc \ub05d\uc758 \ud56d\ub9cc \ub0a8\uac8c \ub429\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \ubb34\ud55c\ud788 \ub354\ud574\uc9c0\ub294 \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\ub3c4 \uc544\uc8fc \uac04\ub2e8\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ub2e4\uc74c \uc218\uc5f4\uc758 \ud569 $S = \\frac{1}{1 \\times 2} + \\frac{1}{2 \\times 3} + \\frac{1}{3 \\times 4} + \\dots + \\frac{1}{n(n+1)}$\uc744 \uad6c\ud558\uc2dc\uc624. \uc774 \ubb38\uc81c\ub294 \ubd84\ubaa8\uac00 \uc5f0\uc18d\ub41c \uc790\uc5f0\uc218\uc758 \uacf1\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc77c\ubc18\ud56d $a_k = \\frac{1}{k(k+1)}$\uc744 \ubd80\ubd84\ubd84\uc218 \uacf5\uc2dd\uc5d0 \ub300\uc785\ud558\uc5ec \ubcc0\ud615\ud569\ub2c8\ub2e4. $$ \\frac{1}{k(k+1)} = \\frac{1}{(k+1) - k} \\left( \\frac{1}{k} - \\frac{1}{k+1} \\right) = \\frac{1}{k} - \\frac{1}{k+1} $$","\uc774\uc81c \uad6c\ud558\uace0\uc790 \ud558\ub294 \ud569 $S$\uc5d0 \ubcc0\ud615\ub41c \uc2dd\uc744 \ub300\uc785\ud558\uc5ec \ub098\uc5f4\ud574 \ubd05\ub2c8\ub2e4. $$ S = \\left( 1 - \\frac{1}{2} \\right) + \\left( \\frac{1}{2} - \\frac{1}{3} \\right) + \\left( \\frac{1}{3} - \\frac{1}{4} \\right) + \\dots + \\left( \\frac{1}{n} - \\frac{1}{n+1} \\right) $$ \uc2dd\uc744 \uc0b4\ud3b4\ubcf4\uba74 $-\\frac{1}{2}$\uc640 $+\\frac{1}{2}$, $-\\frac{1}{3}$\uacfc $+\\frac{1}{3}$ \ub4f1 \uc911\uac04\uc758 \ubaa8\ub4e0 \ud56d\uc774 \uc0c1\uc1c4\ub418\ub294 \uac83\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uacb0\uacfc\uc801\uc73c\ub85c \uccab \ubc88\uc9f8 \ud56d\uc778 $1$\uacfc \ub9c8\uc9c0\ub9c9 \ud56d\uc778 $-\\frac{1}{n+1}$\ub9cc \ub0a8\uac8c \ub429\ub2c8\ub2e4.","\ub530\ub77c\uc11c \ucd5c\uc885\uc801\uc778 \ud569\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\ub9ac\ub429\ub2c8\ub2e4. $$ S = 1 - \\frac{1}{n+1} = \\frac{n+1-1}{n+1} = \\frac{n}{n+1} $$ \uc774\ucc98\ub7fc \ubd80\ubd84\ubd84\uc218\ub97c \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub294 \uc218\uc5f4\uc758 \ud569\ub3c4 \ub2e8\uacc4\ubcc4\ub85c \ucc28\uadfc\ucc28\uadfc \uc811\uadfc\ud558\uc5ec \ub9e4\uc6b0 \uac04\uacb0\ud55c \uacb0\uacfc\uac12\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae30\ubc95\uc740 \uace0\ub4f1\ud559\uad50 \uc218\ud559\uc5d0\uc11c \uc218\uc5f4\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc801\ubd84\uc774\ub098 \uadf9\ud55c \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \ub54c\ub3c4 \uc790\uc8fc \ub4f1\uc7a5\ud558\ubbc0\ub85c \ubc18\ub4dc\uc2dc \uc219\ub2ec\ud574 \ub450\uc5b4\uc57c \ud569\ub2c8\ub2e4."],ai0),t1,B.o)],ai2),t1,B.o)],ai3),s3,s3,s3,"concept_\ubd80\ubd84\ubd84\uc218",0,"","\ub300\uc218 > \uc218\uc5f4 > \uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569 > \ubd80\ubd84\ubd84\uc218",i,t1,s3)
h=A.a(["\ub300\uc218","\uc9c0\uc218\ud568\uc218","\uc9c0\uc218\ud568\uc218\uc758\ud3c9\ud589\uc774\ub3d9"],ai0)
h=A.av(s2,A.a([A.au(A.a(["\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\ud3c9\ud589\uc774\ub3d9 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["\uc9c0\uc218\ud568\uc218\uc758 \ud3c9\ud589\uc774\ub3d9\uc774\ub780 \uae30\ubcf8\uc801\uc778 \uc9c0\uc218\ud568\uc218 $y = a^x$ (\ub2e8, $a > 0, a  eq 1$)\uc758 \uadf8\ub798\ud504\ub97c \uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \uac00\ub85c \ubc29\ud5a5(x\ucd95)\uc774\ub098 \uc138\ub85c \ubc29\ud5a5(y\ucd95)\uc73c\ub85c \ubc00\uc5b4\uc11c \uc62e\uae30\ub294 \uac83\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ud568\uc218 $y = a^x$\uc758 \uadf8\ub798\ud504\ub97c x\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $p$\ub9cc\ud07c, y\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud558\uba74, \uc0c8\ub85c\uc6b4 \ud568\uc218\uc2dd\uc740 $y - q = a^{x - p}$\uac00 \ub418\uba70, \uc774\ub97c \uc815\ub9ac\ud558\uba74 $$y = a^{x - p} + q$$\uac00 \ub429\ub2c8\ub2e4.","\uc774 \ud3c9\ud589\uc774\ub3d9\uc740 \ud568\uc218\uc758 \uadf8\ub798\ud504 \ubaa8\uc591 \uc790\uccb4\ub97c \ubc14\uafb8\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc810\uadfc\uc120\uacfc \uce58\uc5ed\uc5d0 \ubcc0\ud654\ub97c \uc90d\ub2c8\ub2e4. \uc6d0\ub798 \uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \uc810\uadfc\uc120\uc740 x\ucd95\uc778 $y = 0$\uc774\uc5c8\uc73c\ub098, y\ucd95\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud558\uac8c \ub418\uba74 \uc810\uadfc\uc120\uc740 $$y = q$$\ub85c \ubcc0\ud558\uac8c \ub429\ub2c8\ub2e4. \ub610\ud55c, \uc6d0\ub798\uc758 \uce58\uc5ed\uc740 $y > 0$\uc774\uc5c8\uc73c\ub098, \ud3c9\ud589\uc774\ub3d9 \ud6c4\uc5d0\ub294 $$y > q$$\ub85c \ubc14\ub00c\uc5b4 \ud568\uc22b\uac12\uc758 \ubc94\uc704\uac00 \uacb0\uc815\ub429\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \ud568\uc218 $y = 2^{x-1} + 3$\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub824\ubd05\uc2dc\ub2e4. \uc774 \ud568\uc218\ub294 \uae30\ubcf8\ud615\uc778 $y = 2^x$\ub97c x\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $1$\ub9cc\ud07c, y\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $3$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc785\ub2c8\ub2e4. \uc774\ub54c $x$\uc5d0 $1$\uc744 \ub300\uc785\ud558\uba74 $y = 2^0 + 3 = 4$\uac00 \ub418\uc5b4 \uc810 $(1, 4)$\ub97c \uc9c0\ub098\uba70, \uc810\uadfc\uc120\uc740 $y = 3$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ud3c9\ud589\uc774\ub3d9\uc744 \uc774\ud574\ud558\uba74 \ubcf5\uc7a1\ud55c \uc9c0\uc218\ud568\uc218\ub3c4 \uae30\ubcf8\ud615\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud574 \uc27d\uac8c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c \ubb38\uc81c\ub97c \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. '\ud568\uc218 $y = 3^{x+2} - 1$\uc758 \uadf8\ub798\ud504\ub294 $y = 3^x$\uc758 \uadf8\ub798\ud504\ub97c \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc5bc\ub9c8\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc778\uc9c0 \uad6c\ud558\uace0, \uc774 \ud568\uc218\uc758 \uc810\uadfc\uc120\uc744 \ucc3e\uc73c\uc2dc\uc624.'\ub77c\ub294 \ubb38\uc81c\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \uc2dd\uc744 \ud3c9\ud589\uc774\ub3d9\uc758 \uc815\uc758\uc640 \ube44\uad50\ud569\ub2c8\ub2e4. $y = 3^{x - (-2)} - 1$\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc73c\ubbc0\ub85c, x\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $-2$\ub9cc\ud07c, y\ucd95\uc758 \ubc29\ud5a5\uc73c\ub85c $-1$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud588\uc74c\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc810\uadfc\uc120\uc744 \uad6c\ud558\ub294 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \uc9c0\uc218\ud568\uc218 $y = a^{x-p} + q$\uc5d0\uc11c $x$\uac00 \ub9e4\uc6b0 \uc791\uc544\uc9c0\uac70\ub098 \ucee4\uc9c8 \ub54c $a^{x-p}$ \ud56d\uc740 $0$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9d1\ub2c8\ub2e4. \ub530\ub77c\uc11c $y = 3^{x+2} - 1$\uc5d0\uc11c $3^{x+2}$ \ud56d\uc774 $0$\uc5d0 \uac00\uae4c\uc6cc\uc9c8 \ub54c $y$\uac12\uc740 $-1$\uc5d0 \uc218\ub834\ud558\uac8c \ub429\ub2c8\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc774 \ud568\uc218\uc758 \uc810\uadfc\uc120\uc740 $$y = -1$$\uc774 \ub418\uba70, \uce58\uc5ed\uc740 $$y > -1$$\uc774 \ub429\ub2c8\ub2e4."],ai0),t2,B.o)],ai2),t2,B.o)],ai3),s3,s3,s3,"concept_\uc9c0\uc218\ud568\uc218\uc758\ud3c9\ud589\uc774\ub3d9",0,"","\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\ud3c9\ud589\uc774\ub3d9",h,t2,s3)
g=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4","\ud3c9\ud589\uc870\uac74"],ai0)
g=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4 > \ud3c9\ud589\uc870\uac74 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \ub450 \uc9c1\uc120\uc774 \uc11c\ub85c \ub9cc\ub098\uc9c0 \uc54a\uace0 \ub098\ub780\ud788 \ubed7\uc5b4 \ub098\uac00\ub294 \uc0c1\ud0dc\ub97c '\ud3c9\ud589\ud558\ub2e4'\uace0 \ud569\ub2c8\ub2e4. \ub450 \uc9c1\uc120\uc774 \ud3c9\ud589\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub450 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\uac00 \uc11c\ub85c \uac19\uc544\uc57c \ud558\uba70, \ub3d9\uc2dc\uc5d0 y\ucd95\uacfc \ub9cc\ub098\ub294 \uc810\uc778 y\uc808\ud3b8\uc740 \uc11c\ub85c \ub2ec\ub77c\uc57c \ud569\ub2c8\ub2e4. \ub9cc\uc57d \uae30\uc6b8\uae30\uc640 y\uc808\ud3b8\uc774 \ubaa8\ub450 \uac19\ub2e4\uba74 \ub450 \uc9c1\uc120\uc740 \uc11c\ub85c \uc77c\uce58\ud558\uac8c \ub418\uc5b4 \ud3c9\ud589\ud558\ub2e4\uace0 \ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \uc774 \uc810\uc744 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub450 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uac01\uac01 $y = mx + n$\uacfc $y = m'x + n'$\uc774\ub77c\uace0 \ud560 \ub54c, \ub450 \uc9c1\uc120\uc774 \ud3c9\ud589\ud560 \uc870\uac74\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uae30\uc6b8\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 $m$\uacfc $m'$\uc774 \uac19\uace0, y\uc808\ud3b8\uc744 \ub098\ud0c0\ub0b4\ub294 $n$\uacfc $n'$\uc740 \ub2ec\ub77c\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uc218\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\uba74 $$m = m', \\quad n \\neq n'$$ \uc785\ub2c8\ub2e4. \ub9cc\uc57d \uc9c1\uc120\uc774 $ax + by + c = 0$\uacfc $a'x + b'y + c' = 0$\uc758 \uc77c\ubc18\ud615\uc73c\ub85c \uc8fc\uc5b4\uc84c\ub2e4\uba74, \uae30\uc6b8\uae30\uc640 y\uc808\ud3b8\uc744 \ube44\uad50\ud558\uc5ec $$ \\frac{a}{a'} = \\frac{b}{b'} \\neq \\frac{c}{c'} $$ \ub77c\ub294 \uad00\uacc4\uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \ud3c9\ud589\uc870\uac74\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ub450 \uc9c1\uc120 $y = 2x + 3$\uacfc $y = ax - 1$\uc774 \uc11c\ub85c \ud3c9\ud589\ud560 \ub54c, \uc0c1\uc218 $a$\uc758 \uac12\uc744 \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \ud3c9\ud589\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub450 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\uac00 \uac19\uc544\uc57c \ud558\ubbc0\ub85c, \uccab \ubc88\uc9f8 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\uc778 $2$\uc640 \ub450 \ubc88\uc9f8 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\uc778 $a$\uac00 \uac19\uc544\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $a = 2$\uac00 \ub429\ub2c8\ub2e4.","\uc774\ub54c, y\uc808\ud3b8\uc744 \ud655\uc778\ud558\uc5ec \ub450 \uc9c1\uc120\uc774 \uc77c\uce58\ud558\uc9c0 \uc54a\ub294\uc9c0 \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc9c1\uc120\uc758 y\uc808\ud3b8\uc740 $3$\uc774\uace0, \ub450 \ubc88\uc9f8 \uc9c1\uc120\uc758 y\uc808\ud3b8\uc740 $-1$\uc785\ub2c8\ub2e4. $3 \\neq -1$\uc774\ubbc0\ub85c \ub450 \uc9c1\uc120\uc740 \uc77c\uce58\ud558\uc9c0 \uc54a\uc73c\uba70, \ub530\ub77c\uc11c $a = 2$\uc77c \ub54c \ub450 \uc9c1\uc120\uc740 \ud3c9\ud589\ud569\ub2c8\ub2e4.","\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \ud615\ud0dc\uc758 \uc608\uc81c\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \ub450 \uc9c1\uc120 $2x - y + 1 = 0$\uacfc $4x + ky + 3 = 0$\uc774 \ud3c9\ud589\ud558\ub3c4\ub85d \ud558\ub294 \uc0c1\uc218 $k$\uc758 \uac12\uc744 \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ud3c9\ud589\uc870\uac74\uc778 \uacc4\uc218\uc758 \ube44\ub97c \uc774\uc6a9\ud558\uba74 $$ \\frac{2}{4} = \\frac{-1}{k} \\neq \\frac{1}{3} $$ \uc774 \uc131\ub9bd\ud574\uc57c \ud569\ub2c8\ub2e4. \uba3c\uc800 \uc55e\uc758 \ub4f1\uc2dd $\\frac{2}{4} = \\frac{-1}{k}$\ub97c \ud480\uba74, $2k = -4$\uac00 \ub418\uc5b4 $k = -2$\ub97c \uc5bb\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c $k = -2$\uc77c \ub54c \uc0c1\uc218\ud56d\uc758 \ube44\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. $\\frac{2}{4} = \\frac{-1}{-2} = \\frac{1}{2}$\uc774\uace0, \uc0c1\uc218\ud56d\uc758 \ube44\ub294 $\\frac{1}{3}$\uc774\ubbc0\ub85c $\\frac{1}{2} \\neq \\frac{1}{3}$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub450 \uc9c1\uc120\uc740 \uc77c\uce58\ud558\uc9c0 \uc54a\uace0 \ud3c9\ud589\ud558\ubbc0\ub85c, \uad6c\ud558\ub294 \uac12\uc740 $k = -2$\uc785\ub2c8\ub2e4."],ai0),t3,B.o)],ai2),t3,B.o)],ai3),s3,s3,s3,"concept_\ud3c9\ud589\uc870\uac74",0,"","\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \ub450\uc9c1\uc120\uc758\uc704\uce58\uad00\uacc4 > \ud3c9\ud589\uc870\uac74",g,t3,s3)
f=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\uc778\uc218\ubd84\ud574","\uace0\ucc28\uc2dd\uc778\uc218\ubd84\ud574"],ai0)
f=A.av(s2,A.a([A.au(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \uc778\uc218\ubd84\ud574 > \uace0\ucc28\uc2dd\uc778\uc218\ubd84\ud574 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.aw(s3,B.r,A.a(['[   "\uace0\ucc28\uc2dd\uc758 \uc778\uc218\ubd84\ud574\ub780 \ucc28\uc218\uac00 3\ucc28 \uc774\uc0c1\uc778 \ub2e4\ud56d\uc2dd\uc744 \ub450 \uac1c \uc774\uc0c1\uc758 \ub2e4\ud56d\uc2dd\uc758 \uacf1\uc73c\ub85c \ub098\ud0c0\ub0b4\ub294 \uacfc\uc815\uc744 \ub9d0\ud569\ub2c8\ub2e4. 2\ucc28\uc2dd\uc740 \uadfc\uc758 \uacf5\uc2dd\uc774\ub098 \uc778\uc218\ubd84\ud574 \uacf5\uc2dd\uc744 \ud1b5\ud574 \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc9c0\ub9cc, 3\ucc28 \uc774\uc0c1\uc758 \uace0\ucc28\uc2dd\uc740 \'\uc778\uc218\uc815\ub9ac\'\uc640 \'\uc870\ub9bd\uc81c\ubc95\'\uc744 \ud65c\uc6a9\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4. \uc778\uc218\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\uc5d0 \ub300\ud558\uc5ec $P(\\alpha)=0$\uc774\uba74 $P(x)$\ub294 $(x-\\alpha)$\ub97c \uc778\uc218\ub85c \uac00\uc9c4\ub2e4\ub294 \uc131\uc9c8\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.",   "\uace0\ucc28\uc2dd\uc744 \uc778\uc218\ubd84\ud574\ud558\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ub2e4\ud56d\uc2dd\uc758 \uc0c1\uc218\ud56d\uc758 \uc57d\uc218\ub4e4\uc744 \ud6c4\ubcf4\ub85c \ub300\uc785\ud558\uc5ec $P(\\alpha)=0$\uc774 \ub418\ub294 $\\alpha$ \uac12\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \uc774\ub807\uac8c \ucc3e\uc740 \uc778\uc218\ub97c \ubc14\ud0d5\uc73c\ub85c \uc870\ub9bd\uc81c\ubc95\uc744 \uc2dc\ud589\ud558\uba74 \uace0\ucc28\uc2dd\uc744 $(x-\\alpha) \\times Q(x)$ \ud615\ud0dc\ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \ubaab\uc778 $Q(x)$\uac00 2\ucc28\uc2dd\uc774\ub77c\uba74 \ub2e4\uc2dc \uc6b0\ub9ac\uac00 \uc544\ub294 \uc778\uc218\ubd84\ud574 \uacf5\uc2dd\uc744 \uc0ac\uc6a9\ud558\uc5ec \ub05d\uae4c\uc9c0 \ubd84\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d $Q(x)$\uac00 \uc5ec\uc804\ud788 3\ucc28 \uc774\uc0c1\uc774\ub77c\uba74 \uac19\uc740 \uacfc\uc815\uc744 \ubc18\ubcf5\ud558\uc5ec \uc644\uc804\ud788 \uc778\uc218\ubd84\ud574\ud569\ub2c8\ub2e4.",   "\uc870\ub9bd\uc81c\ubc95\uc744 \uc218\ud589\ud560 \ub54c\ub294 \ub2e4\ud56d\uc2dd\uc758 \uac01 \ud56d\uc758 \uacc4\uc218\ub97c \uc21c\uc11c\ub300\ub85c \ub098\uc5f4\ud558\ub418, \ud2b9\uc815 \ucc28\uc218\uc758 \ud56d\uc774 \uc5c6\ub2e4\uba74 \ubc18\ub4dc\uc2dc $0$\uc744 \uc368\uc8fc\uc5b4\uc57c \ud568\uc744 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c, \uc778\uc218\uc815\ub9ac\ub97c \uc774\uc6a9\ud560 \ub54c \ub300\uc785\ud558\ub294 \ud6c4\ubcf4 \uac12\uc740 $\\\\pm \\\\frac{\\\\text{\uc0c1\uc218\ud56d\uc758 \uc57d\uc218}}{\\\\text{\ucd5c\uace0\ucc28\ud56d\uc758 \uacc4\uc218\uc758 \uc57d\uc218}}$ \ubc94\uc704 \ub0b4\uc5d0\uc11c \ucc3e\ub294 \uac83\uc774 \ud6a8\uc728\uc801\uc785\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc744 \ud1b5\ud574 \ubcf5\uc7a1\ud55c \uace0\ucc28\uc2dd\ub3c4 \ucc28\uc218\ub97c \ud558\ub098\uc529 \ub0ae\ucd94\uc5b4 \uac04\ub2e8\ud55c \ub2e4\ud56d\uc2dd\ub4e4\uc758 \uacf1\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc608\uc81c \ubb38\uc81c: \ub2e4\ud56d\uc2dd $P(x) = x^3 - 2x^2 - x + 2$\ub97c \uc778\uc218\ubd84\ud574\ud558\uc2dc\uc624. \uba3c\uc800 $P(x)=0$\uc774 \ub418\ub294 $x$ \uac12\uc744 \ucc3e\uae30 \uc704\ud574 \uc0c1\uc218\ud56d $2$\uc758 \uc57d\uc218\uc778 $\\\\pm 1, \\\\pm 2$\ub97c \ub300\uc785\ud574 \ubd05\ub2c8\ub2e4. $P(1) = 1^3 - 2(1)^2 - 1 + 2 = 1 - 2 - 1 + 2 = 0$\uc774\ubbc0\ub85c, $(x-1)$\uc740 $P(x)$\uc758 \uc778\uc218\uc785\ub2c8\ub2e4.",   "\uc774\uc81c \uc870\ub9bd\uc81c\ubc95\uc744 \uc0ac\uc6a9\ud558\uc5ec $P(x)$\ub97c $(x-1)$\ub85c \ub098\ub215\ub2c8\ub2e4. \uacc4\uc218 $1, -2, -1, 2$\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc870\ub9bd\uc81c\ubc95\uc744 \uc218\ud589\ud558\uba74 \ubaab\uc740 $x^2 - x - 2$\uac00 \ub429\ub2c8\ub2e4. \uc989, $P(x) = (x-1)(x^2 - x - 2)$\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubaab\uc778 $x^2 - x - 2$\ub97c \uc778\uc218\ubd84\ud574\ud558\uba74 $(x-2)(x+1)$\uc774 \ub418\ubbc0\ub85c, \ucd5c\uc885 \uacb0\uacfc\ub294 $P(x) = (x-1)(x-2)(x+1)$\uc785\ub2c8\ub2e4." ]'],ai0),t4,B.o)],ai2),t4,B.o)],ai3),s3,s3,s3,"concept_\uace0\ucc28\uc2dd\uc778\uc218\ubd84\ud574",0,"","\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \uc778\uc218\ubd84\ud574 > \uace0\ucc28\uc2dd\uc778\uc218\ubd84\ud574",f,t4,s3)
